package net.officefloor.hq.app.grade;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/grades")
@Validated
public class GradeController {

    /** A grade as the screen shows it: its code and whether it is retired. */
    public record GradeView(String grade, boolean retired) {
    }

    /** The retire form: the grade to retire. */
    public record RetireForm(@NotNull @Size(max = 10) String grade) {
    }

    /** The merge form: the grade merged and the grade it is merged into. */
    public record MergeForm(@NotNull @Size(max = 10) String from, @NotNull @Size(max = 10) String into) {
    }

    /** How many people a merge gave the other grade. */
    public record Merged(int merged) {
    }

    private final GradeService service;
    private final PersonService people;

    public GradeController(GradeService service, PersonService people) {
        this.service = service;
        this.people = people;
    }

    @GetMapping
    public List<GradeView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        Set<String> retired = service.retired(sheetId.trim()).stream()
                .filter(r -> asOf == null || !r.getRetiredOn().isAfter(asOf))
                .map(RetiredGrade::getGrade).collect(Collectors.toSet());
        return GradeService.GRADES.stream().map(g -> new GradeView(g, retired.contains(g))).toList();
    }

    @PostMapping("/retire")
    public List<GradeView> retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RetireForm form) {
        service.retire(sheetId.trim(), user.trim(), form.grade().trim());
        return list(sheetId, null);
    }

    /** Merge a grade into another: the people on it are given the other (see
     *  {@link PersonService#mergeGrade}). */
    @PostMapping("/merge")
    public Merged merge(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MergeForm form) {
        return new Merged(people.mergeGrade(sheetId.trim(), user.trim(), form.from().trim(), form.into().trim()).size());
    }
}
package net.officefloor.hq.app.grade;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The grades of a sheet and which of them are retired. */
@Service
public class GradeService {

    /** The grades a person can have. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    private final RetiredGradeRepository retired;
    private final SheetService sheets;
    private final Audit audit;

    public GradeService(RetiredGradeRepository retired, SheetService sheets, Audit audit) {
        this.retired = retired;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The grades retired on the sheet, by grade. */
    @Transactional(readOnly = true)
    public List<RetiredGrade> retired(String sheetId) {
        return retired.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /** Whether the grade is retired on the sheet. */
    @Transactional(readOnly = true)
    public boolean isRetired(String sheetId, String grade) {
        return retired.existsBySheetIdAndGrade(sheetId, grade);
    }

    /** Refuse the grade as a choice for a person when it is retired on the sheet. */
    @Transactional(readOnly = true)
    public void checkChoosable(String sheetId, String grade) {
        if (isRetired(sheetId, grade)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Grade " + grade + " is retired");
        }
    }

    /** Retire one of the grades on the sheet; refused when it is no grade or is retired already. It
     *  changes no one: people on it keep it. */
    @Transactional
    public synchronized RetiredGrade retire(String sheetId, String user, String grade) {
        if (!GRADES.contains(grade)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A grade is A, B or C");
        }
        sheets.load(sheetId, user);
        if (retired.existsBySheetIdAndGrade(sheetId, grade)) {
            throw alreadyRetired();
        }
        RetiredGrade saved;
        try {
            saved = retired.saveAndFlush(new RetiredGrade(sheetId, grade, sheets.today(sheetId)));
        } catch (DataIntegrityViolationException e) {
            throw alreadyRetired();
        }
        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + user + " grade=" + grade);
        return saved;
    }

    private static ResponseStatusException alreadyRetired() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That grade is already retired");
    }
}
